-- MAKE.INC Studio Portal · Supabase PostgreSQL schema
-- Paste this file into the Supabase SQL Editor and run ONCE on a fresh project.
-- Never expose Supabase's service-role key in the website.
-- All attendance write timestamps are generated by the database, not by users.

create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default 'Employee',
  email text not null,
  phone text not null default '',
  job_title text not null default 'Employee',
  role text not null default 'employee' check (role in ('employee','admin','principal')),
  is_active boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists public.shifts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  punched_in_at timestamptz not null default now(),
  punched_out_at timestamptz,
  constraint shift_end_after_start check (punched_out_at is null or punched_out_at >= punched_in_at)
);
create unique index if not exists one_open_shift_per_user on public.shifts(user_id) where punched_out_at is null;
create index if not exists shifts_by_user_time on public.shifts(user_id,punched_in_at desc);

create table if not exists public.break_entries (
  id uuid primary key default gen_random_uuid(),
  shift_id uuid not null references public.shifts(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null check (kind in ('tea','lunch')),
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  constraint break_end_after_start check (ended_at is null or ended_at >= started_at)
);
create unique index if not exists one_open_break_per_user on public.break_entries(user_id) where ended_at is null;
create index if not exists break_by_shift on public.break_entries(shift_id);

create table if not exists public.tasks (
  id uuid primary key default gen_random_uuid(),
  title text not null check (length(trim(title)) between 2 and 120),
  description text not null default '',
  project text not null default '',
  assignee_id uuid not null references public.profiles(id) on delete cascade,
  assigned_by uuid not null references public.profiles(id),
  priority text not null default 'medium' check(priority in ('high','medium','low')),
  due_date date,
  status text not null default 'todo' check(status in ('todo','in_progress','done')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists tasks_by_assignee on public.tasks(assignee_id,status);

create table if not exists public.leave_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  type text not null check(type in ('sick','normal')),
  start_date date not null,
  end_date date not null,
  reason text not null check(length(trim(reason))>0),
  status text not null default 'pending' check(status in ('pending','approved','rejected')),
  reviewed_by uuid references public.profiles(id),
  reviewed_at timestamptz,
  manager_note text,
  created_at timestamptz not null default now(),
  constraint leave_dates_ordered check(end_date >= start_date)
);
create index if not exists leaves_by_user on public.leave_requests(user_id,created_at desc);

create table if not exists public.reimbursements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  amount numeric(12,2) not null check(amount>0),
  category text not null check(category in ('Office','Site','Travel','Materials','Other')),
  spent_on date not null,
  description text not null check(length(trim(description))>0),
  receipt_path text,
  status text not null default 'pending' check(status in ('pending','approved','rejected','paid')),
  reviewed_by uuid references public.profiles(id),
  reviewed_at timestamptz,
  manager_note text,
  created_at timestamptz not null default now()
);
create index if not exists expense_by_user on public.reimbursements(user_id,created_at desc);

-- Profile is created by a trusted database trigger upon successful signup.
create or replace function public.create_employee_profile()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
  insert into public.profiles(id,email,full_name,role,is_active)
  values(new.id,coalesce(new.email,''),left(coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),'Employee'),100),'employee',false)
  on conflict(id) do nothing;
  return new;
end;
$$;
drop trigger if exists create_make_inc_profile on auth.users;
create trigger create_make_inc_profile after insert on auth.users
for each row execute function public.create_employee_profile();

-- Account status and role decisions derive from the server-side profiles table.
create or replace function public.staff_active()
returns boolean language sql stable security definer set search_path = public
as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active=true) $$;
create or replace function public.staff_manager()
returns boolean language sql stable security definer set search_path = public
as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active=true and role in ('admin','principal')) $$;

alter table public.profiles enable row level security;
alter table public.shifts enable row level security;
alter table public.break_entries enable row level security;
alter table public.tasks enable row level security;
alter table public.leave_requests enable row level security;
alter table public.reimbursements enable row level security;

create policy "staff can read own profile managers read directory" on public.profiles
for select to authenticated using (id=auth.uid() or public.staff_manager());
create policy "profile owner can edit basic information" on public.profiles
for update to authenticated using(id=auth.uid() and public.staff_active()) with check(id=auth.uid() and public.staff_active());

create policy "read own shifts or managers read staff shifts" on public.shifts
for select to authenticated using ((user_id=auth.uid() and public.staff_active()) or public.staff_manager());
create policy "read own breaks or managers read staff breaks" on public.break_entries
for select to authenticated using ((user_id=auth.uid() and public.staff_active()) or public.staff_manager());
create policy "read assigned tasks or management board" on public.tasks
for select to authenticated using ((assignee_id=auth.uid() and public.staff_active()) or public.staff_manager());

create policy "read own leave or manager requests" on public.leave_requests
for select to authenticated using ((user_id=auth.uid() and public.staff_active()) or public.staff_manager());
create policy "staff may submit pending leave" on public.leave_requests
for insert to authenticated with check(user_id=auth.uid() and public.staff_active() and status='pending' and reviewed_at is null and reviewed_by is null);

create policy "read own reimbursements or manager claims" on public.reimbursements
for select to authenticated using ((user_id=auth.uid() and public.staff_active()) or public.staff_manager());
create policy "staff may submit pending reimbursements" on public.reimbursements
for insert to authenticated with check(user_id=auth.uid() and public.staff_active() and status='pending' and reviewed_at is null and reviewed_by is null);

-- The browser is NOT granted blanket INSERT/UPDATE/DELETE on sensitive tables.
revoke all on public.profiles, public.shifts, public.break_entries, public.tasks,
              public.leave_requests, public.reimbursements from anon, authenticated;
grant select on public.profiles, public.shifts, public.break_entries, public.tasks,
                public.leave_requests, public.reimbursements to authenticated;
grant update(full_name,phone) on public.profiles to authenticated;
grant insert(user_id,type,start_date,end_date,reason) on public.leave_requests to authenticated;
grant insert(user_id,amount,category,spent_on,description,receipt_path) on public.reimbursements to authenticated;

-- Verified, atomic attendance operations, using the DB clock (now()).
create or replace function public.clock_in() returns uuid
language plpgsql security definer set search_path=public as $$
declare v_id uuid;
begin
  if not public.staff_active() then raise exception 'Your account is pending approval'; end if;
  if exists(select 1 from public.shifts where user_id=auth.uid() and punched_out_at is null) then
    raise exception 'Already punched in';
  end if;
  insert into public.shifts(user_id) values(auth.uid()) returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.clock_out() returns void
language plpgsql security definer set search_path=public as $$
declare v_shift public.shifts%rowtype;
begin
  if not public.staff_active() then raise exception 'Your account is pending approval'; end if;
  select * into v_shift from public.shifts where user_id=auth.uid() and punched_out_at is null for update;
  if not found then raise exception 'No active shift'; end if;
  if exists(select 1 from public.break_entries where shift_id=v_shift.id and ended_at is null) then
    raise exception 'End your active break before punching out';
  end if;
  update public.shifts set punched_out_at=now() where id=v_shift.id;
end;
$$;

create or replace function public.begin_break(p_kind text) returns uuid
language plpgsql security definer set search_path=public as $$
declare v_shift public.shifts%rowtype;v_id uuid;
begin
  if not public.staff_active() then raise exception 'Your account is pending approval'; end if;
  if p_kind not in ('tea','lunch') then raise exception 'Invalid break type'; end if;
  select * into v_shift from public.shifts where user_id=auth.uid() and punched_out_at is null for update;
  if not found then raise exception 'Punch in before taking a break'; end if;
  if exists(select 1 from public.break_entries where user_id=auth.uid() and ended_at is null) then
    raise exception 'End your current break first';
  end if;
  insert into public.break_entries(shift_id,user_id,kind) values(v_shift.id,auth.uid(),p_kind) returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.finish_break() returns void
language plpgsql security definer set search_path=public as $$
declare v_id uuid;
begin
  if not public.staff_active() then raise exception 'Your account is pending approval'; end if;
  select id into v_id from public.break_entries where user_id=auth.uid() and ended_at is null for update;
  if not found then raise exception 'No active break'; end if;
  update public.break_entries set ended_at=now() where id=v_id;
end;
$$;

-- Managers assign tasks; assignees may update ONLY their status.
create or replace function public.assign_task(p_title text,p_description text,p_project text,
  p_assignee_id uuid,p_due_date date,p_priority text) returns uuid
language plpgsql security definer set search_path=public as $$
declare v_id uuid;
begin
  if not public.staff_manager() then raise exception 'Management access required'; end if;
  if not exists(select 1 from public.profiles where id=p_assignee_id and is_active=true) then
    raise exception 'Assigned employee must have an active account';
  end if;
  insert into public.tasks(title,description,project,assignee_id,assigned_by,due_date,priority)
  values(trim(p_title),coalesce(p_description,''),coalesce(p_project,''),p_assignee_id,auth.uid(),p_due_date,p_priority)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.update_task_state(p_id uuid,p_status text) returns void
language plpgsql security definer set search_path=public as $$
begin
  if not public.staff_active() then raise exception 'Account pending approval'; end if;
  if p_status not in ('todo','in_progress','done') then raise exception 'Invalid task status'; end if;
  if not exists(select 1 from public.tasks where id=p_id and (assignee_id=auth.uid() or public.staff_manager())) then
    raise exception 'Task not found or access denied';
  end if;
  update public.tasks set status=p_status,updated_at=now() where id=p_id;
end;
$$;

create or replace function public.review_leave_request(p_id uuid,p_decision text,p_note text)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.staff_manager() then raise exception 'Management access required'; end if;
  if p_decision not in ('approved','rejected') then raise exception 'Invalid review decision'; end if;
  update public.leave_requests
    set status=p_decision, manager_note=left(coalesce(p_note,''),1000), reviewed_by=auth.uid(), reviewed_at=now()
    where id=p_id and status='pending';
  if not found then raise exception 'This leave request was already reviewed or does not exist'; end if;
end;
$$;

create or replace function public.review_reimbursement(p_id uuid,p_decision text,p_note text)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.staff_manager() then raise exception 'Management access required'; end if;
  if p_decision not in ('approved','rejected','paid') then raise exception 'Invalid review decision'; end if;
  update public.reimbursements
    set status=p_decision,manager_note=left(coalesce(p_note,''),1000),reviewed_by=auth.uid(),reviewed_at=now()
    where id=p_id and (
      (status='pending' and p_decision in ('approved','rejected'))
      or (status='approved' and p_decision='paid')
    );
  if not found then raise exception 'Invalid claim status transition or record not found'; end if;
end;
$$;

-- Admins can activate ordinary employee accounts, but only a principal
-- can promote anyone to Admin / Principal. No manager can deactivate self.
create or replace function public.update_staff_access(p_id uuid,p_role text,p_is_active boolean)
returns void language plpgsql security definer set search_path=public as $$
declare caller_role text;target_role text;
begin
  select role into caller_role from public.profiles where id=auth.uid() and is_active=true;
  if caller_role not in ('admin','principal') then raise exception 'Management access required'; end if;
  if p_role not in ('employee','admin','principal') then raise exception 'Invalid role'; end if;
  select role into target_role from public.profiles where id=p_id for update;
  if not found then raise exception 'Employee not found'; end if;
  if p_id=auth.uid() and (p_role<>target_role or p_is_active=false) then
    raise exception 'You cannot change or deactivate your own management account';
  end if;
  if caller_role='admin' and (p_role<>target_role or target_role<>'employee') then
    raise exception 'Only the Principal Architect can change roles or edit manager accounts';
  end if;
  update public.profiles set role=p_role,is_active=p_is_active where id=p_id;
end;
$$;

-- RPC permissions are explicit. Only signed-in users may attempt actions;
-- each SECURITY DEFINER function separately checks its own authorization.
revoke execute on function public.clock_in() from public;
revoke execute on function public.clock_out() from public;
revoke execute on function public.begin_break(text) from public;
revoke execute on function public.finish_break() from public;
revoke execute on function public.assign_task(text,text,text,uuid,date,text) from public;
revoke execute on function public.update_task_state(uuid,text) from public;
revoke execute on function public.review_leave_request(uuid,text,text) from public;
revoke execute on function public.review_reimbursement(uuid,text,text) from public;
revoke execute on function public.update_staff_access(uuid,text,boolean) from public;
revoke execute on function public.staff_active() from public;
revoke execute on function public.staff_manager() from public;
grant execute on function public.clock_in(),public.clock_out(),public.begin_break(text),
 public.finish_break(),public.assign_task(text,text,text,uuid,date,text),
 public.update_task_state(uuid,text),public.review_leave_request(uuid,text,text),
 public.review_reimbursement(uuid,text,text),public.update_staff_access(uuid,text,boolean),
 public.staff_active(),public.staff_manager() to authenticated;

-- Private file store for receipts. Objects are accessible only to the
-- submitting employee and their management team, never as public URLs.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('receipts','receipts',false,5242880,array['image/png','image/jpeg','image/webp','application/pdf'])
on conflict(id) do update set public=false,file_size_limit=5242880,
  allowed_mime_types=excluded.allowed_mime_types;
create policy "makeinc employees upload own receipt" on storage.objects for insert to authenticated
with check(bucket_id='receipts' and public.staff_active() and (storage.foldername(name))[1]=auth.uid()::text);
create policy "makeinc staff and managers view receipts" on storage.objects for select to authenticated
using(bucket_id='receipts' and ((storage.foldername(name))[1]=auth.uid()::text or public.staff_manager()));

-- IMPORTANT: BOOTSTRAP THE FIRST PRINCIPAL ACCOUNT AFTER THEY SIGN UP.
-- In Supabase SQL Editor (trusted database admin), replace the email below:
-- update public.profiles
-- set role='principal',job_title='Principal Architect',is_active=true
-- where email='principal@your-office.com';
-- After this, the Principal may approve staff and promote admins in the portal.
